/**
 * @name newRize
 * @author EleanorMay
 * @version 1.0.0
 * @description Red glass FunPay theme with the newRize animated background.
 * @source https://funpay.com/
 */

/* ==UserStyle==
@name           newRize
@namespace      funpay-rpc
@version        1.0.0
@description    Red glass FunPay theme with the newRize animated background.
==/UserStyle== */

@-moz-document url-prefix("https://funpay.com/") {

:root {
    --nr-red: #d71920;
    --nr-scarlet: #ff3038;
    --nr-red-soft: rgba(215, 25, 32, 0.22);
    --nr-surface: rgba(13, 10, 12, 0.54);
    --nr-text: #fff1f1;
    --nr-muted: #d9aaaa;
    --nr-border: rgba(255, 72, 80, 0.32);
    --nr-shadow: 0 14px 40px rgba(0, 0, 0, 0.48);
    --nr-wallpaper: url("data:image/gif;base64,");
}

html,
body {
    min-height: 100%;
    background-color: #090708 !important;
    background-image: none !important;
    color: var(--nr-text) !important;
}

body {
    position: relative !important;
    isolation: isolate;
    font-family: "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
    font-size: 14px;
    line-height: 1.45;
}

body::before {
    content: "";
    position: fixed;
    z-index: 0;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(180deg, rgba(8, 4, 5, 0.38), rgba(8, 3, 4, 0.76)), var(--nr-wallpaper);
    background-position: center top;
    background-size: cover;
    background-repeat: no-repeat;
    filter: blur(10px) saturate(125%);
    transform: scale(1.04);
}

body > * {
    position: relative;
    z-index: 1;
}

.wrapper,
.wrapper-content,
#content,
#content-body,
.main-container,
#content > .container,
#content-body > .container,
.wrapper-content > .container,
.content-promo,
.promo-games,
.promo-games-all,
.promo-game-list {
    background: transparent !important;
}

#header {
    position: relative;
    z-index: 10000 !important;
    background: rgba(10, 6, 8, 0.68) !important;
    border-bottom: 1px solid var(--nr-border) !important;
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.36);
}

a,
.navbar-default .navbar-nav > li > a,
.navbar-brand .logo-color,
.game-title a,
.nav-abc a,
.promo-game-list-title,
.title-mini {
    color: var(--nr-scarlet) !important;
}

a:hover,
.navbar-default .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > li > a:focus,
.nav-abc a:hover {
    color: #ff8589 !important;
}

.panel,
.panel-default,
.panel-body,
.panel-heading,
.block-info,
.showcase,
.showcase-filters,
.showcase-table,
.offer,
.tc,
.content-with-cd-wide,
.promo-cd,
.chat,
.chat-contacts,
.chat-detail,
.modal-content,
[role="dialog"],
.dropdown-menu {
    color: var(--nr-text) !important;
    background: var(--nr-surface) !important;
    border-color: var(--nr-border) !important;
    box-shadow: var(--nr-shadow) !important;
}

.panel-title,
.tc-header,
.tc-price,
.offer .tc-header,
h1, h2, h3, h4, h5,
.game-title a {
    color: var(--nr-text) !important;
}

.tc-price,
.counter-value,
.unit {
    color: var(--nr-scarlet) !important;
}

.form-control,
.form-control-box,
textarea,
select {
    color: var(--nr-text) !important;
    background: rgba(12, 7, 9, 0.48) !important;
    border-color: var(--nr-border) !important;
    border-radius: 8px !important;
}

button,
.btn,
.btn-primary,
.btn-default,
.btn-gray {
    color: #fff !important;
    background: rgba(155, 12, 20, 0.58) !important;
    border-color: rgba(255, 72, 80, 0.38) !important;
    border-radius: 8px !important;
}

button:hover,
.btn:hover,
.btn-primary:hover,
.btn-default:hover,
.btn-gray:hover {
    background: rgba(215, 25, 32, 0.82) !important;
    border-color: var(--nr-scarlet) !important;
}

.promo-cd .cd-container,
.promo-cd .cd,
.promo-cd .cd-satellite,
.promo-cd .social-statistic-list,
.promo-cd .social-statistic {
    display: none !important;
}

.promo-game-list,
.promo-game-list .promo-game-item,
.promo-game-list .promo-game-item:hover,
.promo-game-list .promo-game-item:focus,
.promo-game-list-header,
.promo-game-list-header .nav-abc,
.promo-game-list-header .nav-abc .nav,
.promo-game-list-header .nav-abc ul,
.nav-abc {
    color: var(--nr-text) !important;
    background: transparent !important;
    background-color: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 0 !important;
    border-color: transparent !important;
    box-shadow: none !important;
}

.promo-game-item {
    min-height: 100%;
    padding: 13px 15px !important;
}

.promo-game-item ul a,
.tc-short,
.tc-desc,
.tc-desc-text,
.hint {
    color: var(--nr-muted) !important;
}

.counter-list .counter-item,
.counter-list .counter-item:hover,
.counter-list .counter-item:focus {
    color: var(--nr-text) !important;
    background: rgba(30, 7, 10, 0.36) !important;
    border: 1px solid rgba(255, 72, 80, 0.22) !important;
    border-radius: 18px !important;
}

.counter-list .counter-item.active,
.counter-list .counter-item.active:hover {
    background: rgba(155, 12, 20, 0.62) !important;
    border-color: var(--nr-scarlet) !important;
}

.contact-item.active,
.contact-item.active:hover,
.chat-contacts .contact-item.active {
    color: #fff !important;
    background: rgba(155, 12, 20, 0.68) !important;
    border-color: var(--nr-scarlet) !important;
}

.wrapper-footer,
#footer {
    color: var(--nr-muted) !important;
    background: rgba(8, 4, 5, 0.72) !important;
    border-top: 1px solid var(--nr-border) !important;
}

/* Keep the FunPay header and profile sections dark and readable. */
#header,
#header .navbar,
.navbar-default,
.navbar-default .navbar-collapse,
.navbar-default .navbar-form {
    background: rgba(10, 6, 8, 0.72) !important;
}

#header {
    width: calc(100% + 12px) !important;
    margin-right: -12px !important;
}

.profile,
.profile-header,
.profile-cover,
.profile-cover-container,
.profile-content,
.profile-page,
.profile-page-content,
.profile-content-wrapper,
.bg-light-color,
.bg-light-color > .container,
.bg-light-color .container,
.profile-container,
.profile-data-container,
.review-container,
.review-item,
.review-item-row,
.review-item-answer,
.page-content,
.page-content-full {
    color: var(--nr-text) !important;
    background: rgba(13, 10, 12, 0.62) !important;
    background-color: rgba(13, 10, 12, 0.62) !important;
    border-color: var(--nr-border) !important;
}

.profile [class*="review"],
.profile [class*="feedback"],
.bg-light-color .review-container,
.bg-light-color .review-item,
.bg-light-color .review-item-row,
.bg-light-color .review-item-answer {
    color: var(--nr-text) !important;
    background: rgba(13, 10, 12, 0.68) !important;
    background-color: rgba(13, 10, 12, 0.68) !important;
    border-color: var(--nr-border) !important;
}

/* The homepage promo sphere and its underlay are fully removed. */
.promo-cd::before,
.promo-cd::after,
.promo-cd .cd-container,
.promo-cd .cd,
.promo-cd .cd-satellite,
.promo-cd .social-statistic-list,
.promo-cd .social-statistic,
.promo-cd .cd svg {
    display: none !important;
    background: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border: 0 !important;
}

.promo-cd,
.content-with-cd-wide {
    display: block !important;
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border: 0 !important;
}

/* Profile wrappers stay transparent so the animated wallpaper remains visible while scrolling. */
#content,
#content-body,
.main-container,
.profile .container,
.profile .row,
.profile-content .container,
.profile-page .container,
.profile > .container,
.profile > .container-fluid,
.profile-content,
.profile-page,
.profile-page-content,
.profile-content-wrapper {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
}

}
